"""Maintained source for Audio Fix legal pages. Local preparation; does not deploy."""
from pathlib import Path
from html import escape
root=Path(__file__).resolve().parents[1]/'apps/audiofix'
css='body{font:18px/1.7 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#143d30;background:#f3f8f4;margin:0}main{max-width:760px;margin:auto;padding:56px 24px}h1{font-size:42px;line-height:1.12}h2{font-size:24px;margin-top:32px}a{color:#146e56}nav{display:flex;gap:20px;flex-wrap:wrap}.small{font-size:14px}'
pages={
'':('Audio Fix — repair, normalize and convert audio','''<h1>Make audio work for you.</h1><p>Audio Fix is an iPhone and iPad app in development for channel repair, volume normalization and audio conversion. Import audio or video, preview the result and export a new copy. Channel repair can keep the useful side and play it in both ears.</p><h2>Focused audio repair</h2><p>Media processing stays on your device. The video stream is copied without re-encoding, while audio is encoded as AAC. The original is not overwritten. This is channel routing, not noise removal or recovery of missing or clipped sound.</p><p>One successful export across all tools is free. Previews, cancelled exports and failed repairs do not consume it. Monthly and lifetime plans provide the same unlimited access to all tools. Availability and local prices are shown in the app when Apple loads the products.</p><p>One active audio track is supported. Decodable surround audio is mixed to stereo; disabled alternate tracks are ignored. Multiple simultaneously active audio tracks are not supported. Mono already plays in both ears; it can still be normalized or converted. App Store availability has not been announced.</p>'''),
'privacy':('Audio Fix Privacy Policy','''<h1>Audio Fix Privacy Policy</h1><p>Updated October 22, 2026. Audio Fix is provided by Space Sheep Studio.</p><h2>On-device media processing</h2><p>Selected audio and video files are copied to the app’s local working storage for analysis, playback, repair, volume normalization and conversion. Audio Fix does not upload videos or audio to the developer or third-party AI services. The app has no account, analytics SDK, advertising or tracking SDK.</p><p>Temporary working copies and previews are cleared on the next app launch or when replaced. Completed exports and history are stored locally until you delete them. Device backups may include app data according to your Apple settings. The original selected file is not modified.</p><h2>Photos, Files and sharing</h2><p>The system photo or file picker gives access only to items you select. Saving to Photos requests add-only permission. You may refuse and still share or save to Files. A chosen sharing destination handles exported files under its own policy. The app copies the video stream and its embedded technical information, including orientation and color information. Audio Fix does not promise to remove all embedded metadata; check sensitive files before sharing.</p><h2>Purchases and shared export allowance</h2><p>Apple handles product loading, purchases, restore, subscriptions and transaction verification. The developer does not receive payment card details. Apple processes information according to its own policies. Audio Fix stores the successful export count in local preferences and the device Keychain. Reinstalling the app may not reset the free allowance. Removing the app does not necessarily remove Keychain records or files saved or shared elsewhere.</p><h2>Support and website</h2><p>If you email support, we receive information you choose to send and use it to respond. Do not send personal media unless needed and agreed. Website hosting may process standard connection information such as IP address and browser details under the host’s policies.</p><h2>Your control</h2><p>Delete exports in the app, remove saved copies in Photos or Files, revoke permissions in iOS Settings, or uninstall the app to remove its container. For privacy questions or requests about information you voluntarily sent us, email <a href="mailto:abel0911@icloud.com">abel0911@icloud.com</a>.</p>'''),
'support':('Audio Fix Support','''<h1>Audio Fix Support</h1><p>Contact Space Sheep Studio at <a href="mailto:abel0911@icloud.com?subject=Audio%20Fix%20Support">abel0911@icloud.com</a>. Include your app version, device model and a description of the issue. You do not need to send your private video for general help.</p><h2>Only one ear has sound</h2><p>Choose stereo audio or video, listen to the original with headphones, preview Left → both and Right → both, then select the side with the voice you want. Export creates a new MOV video copy with AAC audio, or an audio-only MP3, M4A or WAV file. Mixing both sides may cancel opposite-phase audio; select one side if a mixed preview becomes quiet.</p><h2>Limits</h2><p>The app cannot recreate missing sound or remove noise or clipping. Silent audio cannot be normalized or repaired, although a silent file can be converted without normalization. Files without an audio track or with multiple simultaneously active audio tracks are not supported. Decodable surround audio is mixed to stereo; disabled alternate tracks are ignored. Mono already plays in both ears; it can still be normalized or converted.</p><h2>Free use and purchases</h2><p>One completed, verified export across all tools is free. Preview, cancellation and failure do not use this allowance. Monthly and lifetime include the same unlimited features. Restore Purchases is in Settings and the purchase screen. Manage or cancel monthly subscriptions through your App Store account. Price loading failures offer a retry; a separate tap is required to purchase after prices load.</p><h2>Saving</h2><p>Use Share to save audio or video to Files. Video outputs can also be saved to Photos with add-only permission. Completed audio and video exports remain in Library. Deleting an export does not refund a consumed free export or remove copies saved elsewhere.</p>'''),
 'terms':('Audio Fix Terms of Use','''<h1>Audio Fix Terms of Use / EULA</h1><p>Updated October 22, 2026.</p><p>Audio Fix is provided by Space Sheep Studio. The app license is governed by the <a href="https://www.apple.com/legal/internet-services/itunes/dev/stdeula/">Apple Standard End User License Agreement</a>.</p><p>One successful export across all tools is free. Optional monthly auto-renewing access and a one-time lifetime unlock include the same audio repair, normalization and conversion features. Actual localized prices are displayed by Apple in the app before purchase. Monthly access renews unless cancelled at least 24 hours before the current period ends. Manage subscriptions in your App Store account; deletion of the app does not cancel a subscription.</p><p>Process and share only media you have permission to use. Channel repair copies or mixes existing audio; it cannot recover missing or clipped sound. Keep your originals. The LAME component is provided under its own open-source license, including modification and debugging rights; these app terms do not override those rights. Its license and corresponding source archive are available in Settings → Open-source software. For help, contact <a href="mailto:abel0911@icloud.com">abel0911@icloud.com</a>.</p>''')}
feature_details = '<h2>Normalize quiet recordings</h2><p>Normalization applies one gain adjustment, aiming for the selected average RMS level (Standard defaults to -18 dBFS RMS) with sample peaks kept below -1 dBFS and a maximum boost of 48 dB. This is not LUFS loudness matching or dynamic compression. Loud transients or the gain limit can prevent reaching the average target. Stereo balance and natural dynamics are preserved; background noise becomes louder too. The app cannot remove noise or repair clipped sound. Normalize audio files or videos, or combine normalization with channel repair or conversion.</p><h2>Simple audio conversion</h2><p>Export MP3 for easy playback and sharing, M4A (AAC) for smaller files, or WAV for uncompressed audio. MP3 and M4A use 48 kHz at 128 kbps mono or 192 kbps stereo. WAV uses 48 kHz 16-bit PCM. MP3 is encoded locally with LAME; its license and corresponding source are included in Settings → Open-source software. Tested input examples include M4A, MP3, WAV, FLAC, AIFF, CAF and AAC. Actual support depends on the codec and file; protected or damaged files may not decode. Floating-point audio above the output range must be normalized before export to avoid clipping. Video inputs can be exported as audio only. The first 12 seconds can be previewed for free; full export processes the whole file.</p>'
for route in ['', 'support']:
    title, body = pages[route]
    pages[route] = (title, body + feature_details)
nav='<nav><a href="/apps/audiofix/">Audio Fix</a><a href="/apps/audiofix/privacy/">Privacy</a><a href="/apps/audiofix/support/">Support</a><a href="/apps/audiofix/terms/">Terms</a></nav>'
for route,(title,body) in pages.items():
 folder=root/route;folder.mkdir(parents=True,exist_ok=True)
 url='https://justcompress.online/apps/audiofix/'+(route+'/' if route else '')
 html='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+escape(title)+'</title><link rel="canonical" href="'+url+'"><style>'+css+'</style></head><body><main>'+nav+body+'<hr>'+nav+'<p class="small">© 2026 Space Sheep Studio</p></main></body></html>'
 (folder/'index.html').write_text(html)
print('Prepared 4 Audio Fix pages. No deployment performed.')
